/**
 * Clarifying questions («الأسئلة الاستيضاحية») — Abu Rannat asks for the
 * missing facts instead of assuming them.
 *
 * Spec: claude/spec-clarification-questions.md (approved by Safi 2026-10-26).
 *
 * Rules this module keeps:
 *  - Every question is fixed text from QUESTION_SETS below. Nothing here is
 *    generated by the LLM, so the same facts always get the same questions.
 *  - Questions never change the classification. They are attached beside the
 *    result; articles change only when the user answers and the facts are
 *    analysed again.
 *  - A cut-off word is never completed and no offence is assumed from it
 *    (golden T28: «واحد سر…» must not become theft).
 *
 * Pure functions only — no database, no network — so the whole module is
 * covered by test-clarification.mjs without credentials.
 */
import { normalizeForKwMatch } from "./kw-matcher.mjs";

export type ClarificationReason =
  | "truncated"        // the text stops mid-word, too short to analyse
  | "ambiguous"        // a grievance with no act, parties or loss stated
  | "constitutional"   // a challenge to a legislative text
  | "administrative"   // a challenge to an administrative decision
  | "open_points";     // one or more examination cards need missing facts

export type ClarificationGroup = {
  /** Question-set id, e.g. "injury" or "card:قتل:وصف". */
  key: string;
  /** Reader-facing heading. For card groups this is the card's own label. */
  titleAr: string;
  questions: string[];
};

export type Clarification = {
  reason: ClarificationReason;
  groups: ClarificationGroup[];
};

// ── Question bank (spec §4) ─────────────────────────────────────────────────

