/** Examination card → question set. Cards not listed (فاحشة:مراجعة,
 * حرابة:فحص, نهب:جرح, قرار:مشروعية, مخدرات:تقديم) have no approved questions
 * yet (spec §4) and ask nothing. */
const CARD_TO_SET: Record<string, string> = {
  "إصابة:وصف": "injury",
  "جرح:وصف": "injury",
  "إصابة:مراجعة": "injury",
  "قتل:وصف": "homicideIntent",
  "مخدرات:قصد الاتجار": "drugsIntent",
  "مخدرات:قصد التعاطي": "drugsIntent",
  "أمانة:فحص": "trust",
  "سرقة:حد": "hadd",
  "حد:مراجعة": "hadd",
  "اشتراك:فحص": "participation",
  "رضا:فحص": "consent",
  "تهديد:فحص": "threat",
  "تزوير:فحص": "forgery",
  "إهمال:فحص": "negligence",
  "إتلاف:بيّنة": "damage",
};

export function questionSetForCard(concept: string): string | null {
  if (CARD_TO_SET[concept]) return CARD_TO_SET[concept];
  // Every attempted-murder card (شروع:سلاح, شروع:سم and the other methods)
  // asks about means, distance and words — the same facts as قتل:وصف.
  if (concept.startsWith("شروع:")) return "homicideIntent";
  return null;
}

// ── Detectors (deterministic, no LLM) ───────────────────────────────────────

function norm(text: string): string {
  return normalizeForKwMatch(text).replace(/\s+/g, " ").trim();
}

function words(text: string): string[] {
  return norm(text.replace(/…|\.{2,}/g, " "))
    .split(" ")
    .filter((w) => /[؀-ۿ]/.test(w));
}

const TOKEN_PREFIXES = ["وال", "فال", "بال", "لل", "ال", "و", "ف", "ب", "ل"];

/** The token and the token without one leading prefix (و ف ب ل ال …). */
function forms(token: string): string[] {
  const out = [token];
  for (const p of TOKEN_PREFIXES) {
    if (token.startsWith(p) && token.length > p.length + 1) out.push(token.slice(p.length));
  }
  return out;
}

/** Phrase needles (with a space) match as a phrase; single words match a
 * whole token (exact) or the start of a token (stem: «دستور» → «الدستورية»).
 * Exact is the default so «حقي» never matches «حقيبتي». */
function has(text: string, needles: string[], mode: "exact" | "stem" = "exact"): boolean {
  const padded = ` ${words(text).join(" ")} `;
  const toks = words(text).flatMap(forms);
  return needles.some((raw) => {
    const n = norm(raw);
    if (n.includes(" ")) return padded.includes(` ${n} `);
    return mode === "exact" ? toks.includes(n) : toks.some((t) => t.startsWith(n));
  });
}

const TRUNCATED_MAX_WORDS = 4;
const AMBIGUOUS_MAX_WORDS = 5;

/** The text stops in an ellipsis and is too short to describe anything:
 * «واحد سر…». A long account that merely ends in «…» is not treated as cut
 * off — it is analysed normally. */
export function isTruncatedShort(facts: string): boolean {
  const raw = facts.trim();
  if (!/(…|\.{2,})$/.test(raw)) return false;
  const n = words(raw).length;
  return n > 0 && n <= TRUNCATED_MAX_WORDS;
}

/** A grievance with nothing to classify: «حقي ضاع», «عندي مشكلة مع شخص».
 * Plain non-legal text («اشتريت قميصًا») carries no grievance word and
 * gets no questions (golden T24/T25 expect only the no-match message). */
const GRIEVANCE_WORDS = [
  "مشكلة", "مشكلتي", "حقي", "حقوقي", "ضاع", "ضاعت", "ظلم", "ظلمني", "مظلوم",
  "نزاع", "خلاف", "شكوى", "أشتكي", "اشتكي", "ضرر", "خسارة", "اعتدى",
];

export function isAmbiguousGrievance(facts: string): boolean {
  const n = words(facts).length;
  return n > 0 && n <= AMBIGUOUS_MAX_WORDS && has(facts, GRIEVANCE_WORDS);
}

// Stems: «دستور» covers دستوري / الدستورية; «تشريعي» covers تشريعية.
const CONSTITUTIONAL_STEMS = ["دستور"];
const CONSTITUTIONAL_PHRASES = ["نص تشريعي", "نصا تشريعيا", "عدم دستورية"];
const ADMIN_BODY_PHRASES = ["جهة إدارية", "جهة ادارية", "جهة حكومية", "الخدمة المدنية"];
const DECISION_STEMS = ["قرار"];
const ADMINISTRATIVE_STEMS = ["إداري", "اداري", "تظلم", "فصل", "ترخيص", "ترقية", "معاش", "وظيف"];

export function detectPublicLawDomain(facts: string): "constitutional" | "administrative" | null {
  if (has(facts, CONSTITUTIONAL_STEMS, "stem") || has(facts, CONSTITUTIONAL_PHRASES)) {
    return "constitutional";
  }
  if (has(facts, ADMIN_BODY_PHRASES)) return "administrative";
  if (has(facts, DECISION_STEMS, "stem") && has(facts, ADMINISTRATIVE_STEMS, "stem")) {
    return "administrative";
  }
  return null;
}

// ── Assembly ────────────────────────────────────────────────────────────────

/** What buildClarification needs from a CaseMapResult (kept structural so
 * this module does not import analyze.ts). */
export type ClarificationInputResult = {
  laws: Array<{ lawSlug?: string | null }>;
  noConfidentMatch: boolean;
  hasAnyResults: boolean;
  discuss?: Array<{ concept: string; label: string }>;
};

const CRIMINAL_SLUG_PREFIXES = ["criminal-law-", "narcotics-"];

function hasCriminalArticle(r: ClarificationInputResult): boolean {
  return r.laws.some((l) => CRIMINAL_SLUG_PREFIXES.some((p) => (l.lawSlug ?? "").startsWith(p)));
}

function group(key: string, titleAr?: string): ClarificationGroup {
  const set = QUESTION_SETS[key];
  return { key, titleAr: titleAr ?? set.titleAr, questions: [...set.questions] };
}

function cardGroups(r: ClarificationInputResult): ClarificationGroup[] {
  const out: ClarificationGroup[] = [];
  const seen = new Set<string>();
  for (const d of r.discuss ?? []) {
    const setKey = questionSetForCard(d.concept);
    if (!setKey || seen.has(setKey)) continue;
    seen.add(setKey);
    out.push(group(setKey, d.label || undefined));
  }
  return out;
}

/** The clarification to attach to a finished analysis, or null. */
export function buildClarification(
  facts: string,
  r: ClarificationInputResult,
): Clarification | null {
  const cards = cardGroups(r);

  if (isTruncatedShort(facts)) {
    return { reason: "truncated", groups: [group("truncated")] };
  }
  if (r.noConfidentMatch && !r.hasAnyResults && isAmbiguousGrievance(facts)) {
    return { reason: "ambiguous", groups: [group("ambiguous")] };
  }
  if (!hasCriminalArticle(r)) {
    const domain = detectPublicLawDomain(facts);
    if (domain) return { reason: domain, groups: [group(domain), ...cards] };
  }
  if (cards.length) return { reason: "open_points", groups: cards };
  return null;
}
